// Mirror Lake objects: lilies and lotus, reeds, willows, rocks and islets, boats, jetty props, herons, the torii landmark, boathouse, overlays.
import { T, P, rng, hash, f, ell, circ, rect, path, line, ink, tuft, maker, SUBS, sh, trunk, bloom, scat, sparkle, glowC, broad, rockS, fronds, blobPath, leafS, shimenawa } from './sub.mjs';
