import { koi, ripple, ring, stoneW, pebbleSmall } from './water-lib.mjs';
import { refl, lilyPad, lotusBloom, PADC } from './lake-lib.mjs';

const SUB = SUBS.lake, { mk, out } = maker(SUB);
const wpatch = (cx, cy, rx, ry) => ell(cx, cy, rx, ry, '#f6f3e6', .38) + ell(cx, cy, rx * .86, ry * .8, '#9fd0dc', .55);
const vein = (x, y, r, n, col) => { let d = ''; for (let i = 0; i < n; i++) { const a = i / n * 6.283; d += `M${f(x)} ${f(y)}L${f(x + Math.cos(a) * r * .92)} ${f(y + Math.sin(a) * r * .55)}`; } return line(d, col, .6, .55); };
const bigLeaf = (t, x, y, r, tilt = 0, dew = false, col = ['#a8dc88', '#5fae5c', '#2f6e3a']) => ell(x + 1.4, y + 2.6, r, r * .56, '#1d4a63', .14) + `<g transform="rotate(${tilt} ${f(x)} ${f(y)})">` + ell(x, y, r, r * .58, t.rg(col, .35, .3, .9), 1, 0, ink('#1d4a26', .8, .7)) + vein(x, y, r, 9, '#2f6e3a') + ell(x - r * .3, y - r * .2, r * .4, r * .15, '#fff', .35, -12) + (dew ? circ(x - 1, y - 1, 1.5, '#fff', .9) + circ(x - 1.4, y - 1.4, .6, '#cfeaf0') : '') + '</g>';
const stalk = (x0, y0, x1, y1, col = '#4a9a50', w = 1.6) => line(`M${f(x0)} ${f(y0)}Q${f((x0 + x1) / 2 + 2)} ${f((y0 + y1) / 2)} ${f(x1)} ${f(y1)}`, col, w, 1);

// ============================ lily pads and lotus (cell, transparent over water) ============================
const LILY = { a: [[24, 36, 8, 20], [42, 30, 7, 200], [38, 46, 6, 100]], b: [[20, 28, 5.6, 0], [34, 24, 6, 60], [44, 36, 6.4, 140], [28, 42, 6, 220], [40, 48, 5, 300]] };
for (const [v, pads] of Object.entries(LILY)) { const t = mk('grass', 'lily-pads', v); t.add(wpatch(32, 38, 26, 15)); pads.forEach(([x, y, r, a], i) => t.add(lilyPad(x, y, r, a, PADC[i % 4]))); out(t, 'grass', 'lily-pads', v, ['water-overlay', 'mirror-lake', 'lily']); }
for (const [v, kind, bud] of [['c', 'white', false], ['d', 'pink', false], ['e', 'pink', true]]) {
  const t = mk('grass', 'lily-pads', v); t.add(wpatch(32, 40, 26, 14), lilyPad(22, 44, 7, 30, PADC[1]), lilyPad(46, 46, 6, 200, PADC[2]), lilyPad(34, 40, 9, 100, PADC[0]));
  if (bud) t.add(stalk(34, 40, 36, 26, '#4a9a50', 1.3), path('M36 27Q32 22 36 15Q40 22 36 27Z', '#f6a8c0', 1, ink('#d0688a', .6, .8)), path('M36 27Q33 24 36 18', 'none', 1, { fill: 'none', stroke: '#fff', 'stroke-opacity': .5, 'stroke-width': .8 }));
  else t.add(lotusBloom(34, 40, .8, kind, 1)); out(t, 'grass', 'lily-pads', v, ['water-overlay', 'mirror-lake', 'lily', 'flower', bud ? 'bud' : kind]);
}
{ const t = mk('grass', 'lily-pads', 'f'); t.add(wpatch(32, 40, 26, 14)); [[22, 42, 7, 30], [42, 36, 7, 200], [36, 48, 6, 100]].forEach(([x, y, r, a]) => t.add(lilyPad(x, y, r, a, ['#d8b058', '#8a6420']), circ(x + 1, y, 1.2, '#9fd0dc'), ell(x - 2, y - 1, 2, 1, '#a07030', .8))); out(t, 'grass', 'lily-pads', 'f', ['water-overlay', 'mirror-lake', 'lily', 'autumn']); }
// lotus: big leaves on tall stalks with a flower
